using System.Data.Common;
using Microsoft.AspNetCore.Diagnostics;
using Microsoft.AspNetCore.Mvc;
using Microsoft.AspNetCore.Mvc.RazorPages;

[IgnoreAntiforgeryToken] // the exception handler replays POSTs; a missing token must not turn a 500 into a 400
public class StatusModel : PageModel
{
    public string Heading { get; private set; } = "Something went wrong";
    public string Text { get; private set; } = "Please try again in a few minutes.";

    public void OnGet(int code) => Render(code);
    public void OnPost(int code) => Render(code);

    private void Render(int code)
    {
        if (code is < 400 or > 599) code = 404; // someone browsing to /error/200 must not get a 200 error page
        // RTE-007: a failed dependency is 503, never 404 and never a 200 shell.
        if (Unavailable(HttpContext.Features.Get<IExceptionHandlerFeature>()?.Error)) code = 503;
        Response.StatusCode = code; // keeps the real status; this is also where a failed dependency becomes 503 instead of the handler's 500
        (Heading, Text) = code switch
        {
            404 => ("Page not found", "We could not find that page."),
            410 => ("This page has been removed", "It is no longer available."),
            >= 400 and < 500 => ("This page is not available", "Please check the address."),
            _ => ("Something went wrong", "Please try again in a few minutes."),
        };
    }

    private static bool Unavailable(Exception? e)
    {
        for (; e is not null; e = e.InnerException)
            if (e is DbException or TimeoutException or HttpRequestException) return true;
        return false;
    }
}
