using System.Threading.RateLimiting;

builder.Services.AddRazorPages();
builder.Services.AddHttpClient("webhook", c => c.Timeout = TimeSpan.FromSeconds(8)); // delivery timeout
builder.Services.AddRateLimiter(o =>
{
    o.RejectionStatusCode = StatusCodes.Status429TooManyRequests; // SEC-054
    o.AddPolicy("contact", ctx => HttpMethods.IsPost(ctx.Request.Method)
        ? RateLimitPartition.GetFixedWindowLimiter(
            ctx.Connection.RemoteIpAddress?.ToString() ?? "unknown",
            _ => new FixedWindowRateLimiterOptions { PermitLimit = 5, Window = TimeSpan.FromMinutes(10), QueueLimit = 0 })
        : RateLimitPartition.GetNoLimiter("read")); // viewing the page is not limited
});

// ... pipeline: UseRouting() first, then:
app.UseRateLimiter(); // after UseRouting, because the policy is attached to a page
