using System.ComponentModel.DataAnnotations;
using System.Net.Http.Json;
using Microsoft.AspNetCore.Mvc;
using Microsoft.AspNetCore.Mvc.RazorPages;
using Microsoft.AspNetCore.RateLimiting;

[EnableRateLimiting("contact")] // on the page class, not on a handler
public class ContactModel(IHttpClientFactory httpClients, IConfiguration config, ILogger<ContactModel> log) : PageModel
{
    [BindProperty, Required, StringLength(100)] public string Name { get; set; } = "";
    [BindProperty, Required, EmailAddress, StringLength(254)] public string Email { get; set; } = "";
    [BindProperty, Required, StringLength(5000)] public string Message { get; set; } = "";
    [BindProperty] public string? Website { get; set; } // honeypot (SEC-055); nullable, or an empty value fails the implicit [Required]

    public void OnGet() { }

    public async Task<IActionResult> OnPostAsync(CancellationToken ct)
    {
        if (!string.IsNullOrEmpty(Website)) return Done(); // honeypot filled: look successful, do nothing
        if (!ModelState.IsValid)
        {
            Response.StatusCode = StatusCodes.Status400BadRequest;
            return Page(); // re-render with the field errors
        }
        try
        {
            var client = httpClients.CreateClient("webhook");
            // the real destination (UX-001); replace with your provider's call if it is not a webhook
            using var res = await client.PostAsJsonAsync(config["FORM_WEBHOOK_URL"], new { Name, Email, Message }, ct);
            res.EnsureSuccessStatusCode(); // RES-008: a non-2xx answer is a failure
        }
        catch (Exception ex) when (ex is HttpRequestException or TaskCanceledException) // refused, non-2xx, or timeout
        {
            log.LogWarning(ex, "contact delivery failed");
            return StatusCode(StatusCodes.Status502BadGateway); // 5xx page, never the success state
        }
        return Done();
    }

    private IActionResult Done()
    {
        Response.Headers.Location = Url.Page("/ContactThanks"); // RedirectToPage would answer 302; POST-redirect-GET wants 303
        return StatusCode(StatusCodes.Status303SeeOther);
    }
}
