ASP.NET Core 9/10 (Razor Pages, minimal APIs; compiled and run on 9.0.21 and 10.0.13). ASP.NET Core has no built-in CSP nonce, so one small middleware makes a 16-byte random nonce per request, keeps it in HttpContext.Items and writes every header in Response.OnStarting (runs just before the headers are sent, so it also covers error pages and status-code re-executions, which reuse HttpContext.Items). A nonce CSP means every page is rendered per request (no output caching of HTML). UseHsts only writes on HTTPS requests and skips localhost; behind a TLS-terminating proxy enable the Forwarded Headers middleware first. MapStaticAssets fingerprints files at build time and serves the fingerprinted URLs with `Cache-Control: max-age=31536000, immutable` (names like site.j1gj83w5d9.js; files that are not fingerprinted get `no-cache` plus an ETag) and the middleware below adds the `public` that PRF-008 asks for next to `immutable`; `MapRazorPages().WithStaticAssets()` plus `asp-append-version="true"` on <link>/<script> makes the tag helpers emit those fingerprinted URLs. Check with `curl -I`. Remove the template's inline `<script type="importmap">` (or give it the nonce): it is an inline script. Run deployed environments with ASPNETCORE_ENVIRONMENT=Production: in Development the developer exception page shows stack traces (SEC-007).
### file: SecurityHeadersMiddleware.cs
using System.Security.Cryptography;

public sealed class SecurityHeadersMiddleware(RequestDelegate next)
{
    public const string NonceKey = "csp-nonce";

    public Task InvokeAsync(HttpContext context)
    {
        var nonce = Convert.ToBase64String(RandomNumberGenerator.GetBytes(16)); // fresh per response
        context.Items[NonceKey] = nonce;

        context.Response.OnStarting(() =>
        {
            var h = context.Response.Headers;
            // SEC-010 / SEC-075: nonce + strict-dynamic (host sources ignored), no unsafe-inline, object-src and base-uri locked, frame-ancestors present.
            // With analytics add to connect-src: https://www.google-analytics.com https://*.google-analytics.com https://*.analytics.google.com
            // and to img-src: https://www.google-analytics.com (never put Google hosts in script-src; see the consent-loader recipe).
            h["Content-Security-Policy"] =
                $"default-src 'self'; script-src 'self' 'nonce-{nonce}' 'strict-dynamic'; style-src 'self' 'nonce-{nonce}'; " +
                "img-src 'self' data:; font-src 'self'; connect-src 'self'; object-src 'none'; base-uri 'self'; " +
                "form-action 'self'; frame-ancestors 'none'; upgrade-insecure-requests";
            h["X-Content-Type-Options"] = "nosniff";
            h["Referrer-Policy"] = "strict-origin-when-cross-origin";
            h["Permissions-Policy"] = "camera=(), microphone=(), geolocation=()";
            // PRF-008: HTML revalidates; pages that already set Cache-Control (antiforgery pages send no-cache, no-store) keep theirs.
            if (context.Response.ContentType?.StartsWith("text/html", StringComparison.OrdinalIgnoreCase) == true
                && !h.ContainsKey("Cache-Control"))
            {
                h["Cache-Control"] = "public, max-age=0, must-revalidate";
            }
            // PRF-008 wants `public` next to `immutable`; MapStaticAssets sends only "max-age=31536000, immutable" for fingerprinted files.
            var cc = h.CacheControl.ToString();
            if (cc.Contains("immutable", StringComparison.Ordinal) && !cc.Contains("public", StringComparison.Ordinal))
            {
                h.CacheControl = "public, " + cc;
            }
            return Task.CompletedTask;
        });

        return next(context);
    }
}
