ASP.NET Core 9/10 minimal API endpoints. Environment mode comes from DEPLOY_ENV only (`production` is the one production value), read from configuration (environment variables) at run time, never from ASPNETCORE_ENVIRONMENT or IHostEnvironment: that variable is a different switch (Development shows stack traces) and must not decide indexing. Set SITE_URL (for example https://example.com, no trailing slash). Delete wwwroot/robots.txt and wwwroot/sitemap.xml so these endpoints are the only source. Replace PublicPaths with the indexable public pages (200, canonical, not noindex), in the same canonical form as your canonical tags; above 50,000 URLs or 50 MB use a sitemap index.
### file: Program.cs (after `var app = builder.Build();`)
using System.Text;
using System.Xml.Linq;

var production = string.Equals(app.Configuration["DEPLOY_ENV"], "production", StringComparison.Ordinal); // IDX-005
var siteUrl = (app.Configuration["SITE_URL"] ?? "https://example.com").TrimEnd('/');
string[] publicPaths = ["/", "/about", "/contact", "/privacy"]; // your indexable pages

// Non-production: EVERY response (pages, assets, errors, robots.txt) carries X-Robots-Tag. Register this first in the pipeline.
if (!production)
{
    app.Use((context, next) =>
    {
        context.Response.OnStarting(() =>
        {
            context.Response.Headers["X-Robots-Tag"] = "noindex, nofollow";
            return Task.CompletedTask;
        });
        return next(context);
    });
}

app.MapGet("/robots.txt", () =>
{
    if (!production) return Results.Text("User-agent: *\nDisallow: /\n", "text/plain", Encoding.UTF8); // no Sitemap line outside production
    // Disallow only app/API/private paths, never CSS, JS or image paths
    return Results.Text($"User-agent: *\nAllow: /\nDisallow: /api/\n\nSitemap: {siteUrl}/sitemap.xml\n", "text/plain", Encoding.UTF8);
});

app.MapGet("/sitemap.xml", () =>
{
    if (!production) return Results.NotFound(); // non-production: no sitemap
    XNamespace ns = "http://www.sitemaps.org/schemas/sitemap/0.9";
    var doc = new XDocument(
        new XDeclaration("1.0", "utf-8", null),
        new XElement(ns + "urlset", publicPaths.Select(p => new XElement(ns + "url", new XElement(ns + "loc", siteUrl + p))))); // XElement escapes & < >
    return Results.Text(doc.Declaration + "\n" + doc.ToString(), "application/xml", Encoding.UTF8);
});
